// Types a phrase out, holds it, deletes it, moves to the next. Returns "" and
// stops entirely when inactive so a focused composer never fights the caret.
function useTypewriter(phrases, active) {
  const [text, setText] = useState("");

  useEffect(() => {
    if (!active || prefersReducedMotion()) {
      setText("");
      return undefined;
    }

    let index = 0;
    let chars = 0;
    let deleting = false;
    let timer;

    const tick = () => {
      const phrase = phrases[index % phrases.length];
      chars += deleting ? -1 : 1;
      setText(phrase.slice(0, chars));

      let delay = deleting ? 24 : 46;
      if (!deleting && chars === phrase.length) {
        deleting = true;
        delay = 2200;
      } else if (deleting && chars === 0) {
        deleting = false;
        index += 1;
        delay = 320;
      }
      timer = setTimeout(tick, delay);
    };

    timer = setTimeout(tick, 900);
    return () => clearTimeout(timer);
  }, [phrases, active]);

  return text;
}

// Plays the canned trace as if it were happening: reasoning first, then each
// tool call going running → done on its own recorded duration. It is labelled
// "Example" throughout — the point is to show the shape of a turn, not to pass
// a recording off as a live one.
function useSamplePlayback(enabled) {
  const [state, setState] = useState({ lines: [], thinking: "", meta: "" });
  const [playing, setPlaying] = useState(false);
  const [run, setRun] = useState(0);

  const replay = useCallback(() => setRun((n) => n + 1), []);

  useEffect(() => {
    if (!enabled) return undefined;

    if (prefersReducedMotion()) {
      setState({
        lines: SAMPLE_TRACE,
        thinking: SAMPLE_REASONING,
        meta: SAMPLE_META,
      });
      return undefined;
    }

    const timers = [];
    const at = (ms, fn) => timers.push(setTimeout(fn, ms));

    setState({ lines: [], thinking: "", meta: "" });
    setPlaying(true);

    // Reasoning arrives word by word, the way streamed thinking actually does.
    const words = SAMPLE_REASONING.split(" ");
    let clock = run === 0 ? 700 : 150;
    words.forEach((_, i) => {
      at(clock, () =>
        setState((s) => ({ ...s, thinking: words.slice(0, i + 1).join(" ") }))
      );
      clock += 26;
    });

    clock += 350;
    // Each tool call: appears "running", resolves after its recorded latency.
    // The wall-clock numbers are compressed so the whole example lands in a
    // few seconds; the displayed `ms` stays the real recorded one.
    SAMPLE_TRACE.forEach((tool, i) => {
      at(clock, () =>
        setState((s) => ({
          ...s,
          lines: [
            ...SAMPLE_TRACE.slice(0, i).map((t) => ({ ...t })),
            { ...tool, state: "running", ok: undefined, ms: null },
          ],
        }))
      );
      clock += Math.max(520, tool.ms * 0.7);
      at(clock, () =>
        setState((s) => ({
          ...s,
          lines: SAMPLE_TRACE.slice(0, i + 1).map((t) => ({ ...t })),
        }))
      );
      clock += 220;
    });

    at(clock + 200, () => {
      setState((s) => ({ ...s, meta: SAMPLE_META }));
      setPlaying(false);
    });

    return () => timers.forEach(clearTimeout);
  }, [enabled, run]);

  return { ...state, playing, replay };
}

