function CopyButton({ text, className = "" }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(
    (e) => {
      e.stopPropagation();
      if (!text) return;
      navigator.clipboard.writeText(text).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    },
    [text]
  );

  return (
    <button
      type="button"
      className={`jv-copy-btn ${copied ? "jv-copy-copied" : ""} ${className}`}
      onClick={handleCopy}
      title={copied ? "Copied to clipboard!" : "Copy response"}
      aria-label={copied ? "Copied to clipboard" : "Copy text"}
    >
      {copied ? (
        <>
          <span className="jv-copy-icon">✓</span>
          <span className="jv-copy-text">Copied</span>
        </>
      ) : (
        <>
          <span className="jv-copy-icon">📋</span>
          <span className="jv-copy-text">Copy</span>
        </>
      )}
    </button>
  );
}

// ============================================
// SOURCE NOTE — where this particular answer came from
//
// The one rule this page has is that it never claims to be live when it isn't.
// A live turn needs no label (the session bar already says live); a recorded
// or doc-backed one says so plainly, and offers the live agent as the next
// click rather than hiding that it exists.
// ============================================
function SourceNote({ turn, onAskLive, disabled }) {
  if (!turn.source || turn.source === "live") return null;

  if (turn.source === "recorded") {
    return (
      <p className="jv-source jv-source-recorded">
        <span className="jv-source-tag">recorded</span>A real turn, captured
        {turn.capturedAt ? ` on ${turn.capturedAt}` : ""} and replayed at its
        original timings — the tool calls above genuinely ran. Suggested
        questions are served this way so your live questions aren't spent on
        them.
      </p>
    );
  }

  return (
    <p className="jv-source jv-source-docs">
      <span className="jv-source-tag">from the docs</span>
      Answered from {turn.docSource}
      {turn.docSection ? ` · ${turn.docSection}` : ""} — written about the real
      system, not generated just now.
      {turn.askedLive && (
        <button
          type="button"
          className="jv-escalate"
          onClick={onAskLive}
          disabled={disabled}
        >
          Ask Jarvis live instead →
        </button>
      )}
    </p>
  );
}

// ============================================
// CALL RENDERING
// ============================================
const CALL_TOKEN = /("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:True|False|None)\b|\b\d+(?:\.\d+)?\b|[A-Za-z_]\w*(?=\s*=))/g;

function tokenClass(token) {
  if (token[0] === '"' || token[0] === "'") return "jv-t-str";
  if (/^(True|False|None)$/.test(token)) return "jv-t-kw";
  if (/^\d/.test(token)) return "jv-t-num";
  return "jv-t-arg";
}

function CallCode({ text }) {
  const match = /^([A-Za-z_]\w*)\(([\s\S]*)\)$/.exec(text || "");
  if (!match) return <>{text}</>;
  const [, name, args] = match;
  return (
    <>
      <span className="jv-t-fn">{name}</span>
      <span className="jv-t-punc">(</span>
      {args.split(CALL_TOKEN).map((part, i) =>
        i % 2 === 1 ? (
          <span className={tokenClass(part)} key={i}>
            {part}
          </span>
        ) : (
          <span className="jv-t-punc" key={i}>
            {part}
          </span>
        )
      )}
      <span className="jv-t-punc">)</span>
    </>
  );
}

function formatMs(ms) {
  return ms < 1000 ? `${Math.round(ms)}ms` : `${(ms / 1000).toFixed(1)}s`;
}

// ============================================
// TRACE — one turn's machinery, inline
// ============================================
function Trace({
  lines,
  thinking,
  meta,
  busy,
  open,
  onToggle,
  sample,
  elapsed,
  action,
}) {
  const tools = lines.filter((line) => line.kind === "tool");
  const done = tools.filter((t) => t.state === "done").length;
  const failed = lines.some((line) => line.kind === "err");
  const running = busy || tools.some((t) => t.state === "running");

  let label;
  if (sample && running) label = "Example turn — playing";
  else if (sample) label = "Example — ask a question to run a real one";
  else if (busy && tools.length === 0) label = "Working";
  else if (busy) label = `Step ${done + 1} of ${tools.length}`;
  else if (failed) label = "Stopped before answering";
  else if (tools.length === 0) label = "Answered directly — no tools needed";
  else label = `Completed ${tools.length} step${tools.length === 1 ? "" : "s"}`;

  const rightMeta = busy && elapsed ? elapsed : meta;

  return (
    <div
      className={`jv-trace ${sample ? "jv-trace-sample" : ""} ${
        running ? "jv-trace-running" : ""
      }`}
    >
      <div className="jv-trace-head-row">
        <button
          type="button"
          className="jv-trace-head"
          onClick={onToggle}
          aria-expanded={open}
          aria-label={`Execution trace: ${label}`}
        >
          <span className={`jv-chev ${open ? "jv-chev-open" : ""}`}>›</span>
          <span className="jv-traj-tag">trajectory</span>
          <span className="jv-trace-label">{label}</span>
          {busy && <span className="jv-dots" aria-hidden="true" />}
          {rightMeta && <span className="jv-trace-meta">{rightMeta}</span>}
        </button>
        {action}
      </div>

      {open && (
        <div
          className="jv-term"
          role="region"
          aria-label="Terminal Trace Output"
        >
          <div className="jv-term-bar">
            <span className="jv-tdot jv-tdot-r" />
            <span className="jv-tdot jv-tdot-y" />
            <span className="jv-tdot jv-tdot-g" />
            <span className="jv-term-title">
              jarvis@vercel&nbsp;·&nbsp;~/JarvisAssistant
            </span>
            {running && (
              <span className="jv-term-live" aria-hidden="true">
                <i />
                {sample ? "example" : "live"}
              </span>
            )}
          </div>

          <div className="jv-traj-legend">
            <span className="jv-lane jv-lane-think">think</span>
            <span className="jv-lane jv-lane-tool">tool</span>
            <span className="jv-lane jv-lane-result">result</span>
            <span className="jv-lane jv-lane-net">net</span>
            <span className="jv-traj-legend-txt">
              the real record — every step, in order, nothing hidden
            </span>
          </div>

          <div className="jv-term-body">
            {thinking && (
              <div className="jv-reason">
                <div className="jv-reason-label">
                  <span className="jv-lane jv-lane-think">think</span>
                  reasoning
                </div>
                <div className="jv-reason-text">{thinking}</div>
              </div>
            )}

            {lines.map((line, i) => {
              if (line.kind === "tool") {
                return (
                  <div className="jv-tool-block" key={i}>
                    <div className="jv-tool">
                      <span className="jv-lane jv-lane-tool">tool</span>
                      <span
                        className={`jv-tool-step ${
                          line.state === "running" ? "jv-step-running" : ""
                        }`}
                      >
                        {line.step}
                      </span>
                      <code className="jv-tool-call">
                        <CallCode text={line.call || `${line.name}(…)`} />
                      </code>
                      {line.ms != null && (
                        <span className="jv-tool-ms">{formatMs(line.ms)}</span>
                      )}
                      <span
                        className={`jv-tool-state jv-tool-${
                          line.state === "running"
                            ? "running"
                            : line.ok
                            ? "ok"
                            : "err"
                        }`}
                      >
                        {line.state === "running" ? "⋯" : line.ok ? "✓" : "✗"}
                      </span>
                    </div>
                    {line.summary && (
                      <div className="jv-tool-summary">
                        <span
                          className={`jv-lane jv-lane-result ${
                            line.ok === false ? "jv-lane-err" : ""
                          }`}
                        >
                          result
                        </span>
                        {line.summary}
                      </div>
                    )}
                  </div>
                );
              }
              return (
                <div className={`jv-tline jv-tline-${line.kind}`} key={i}>
                  <span
                    className={`jv-lane ${
                      line.kind === "err" ? "jv-lane-err" : "jv-lane-net"
                    }`}
                  >
                    {line.kind === "err" ? "error" : "net"}
                  </span>
                  {line.text}
                </div>
              );
            })}

            {busy && (
              <div className="jv-tline jv-tline-dim">
                working
                <span className="jv-dots" aria-hidden="true" />
              </div>
            )}

            {meta && (
              <div className="jv-tline jv-tline-ok">
                <span className="jv-lane jv-lane-done">done</span>
                {meta}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

