const JarvisLive = ({ theme, setTheme }) => {
  const [input, setInput] = useState("");
  const [turns, setTurns] = useState([]);
  const [streaming, setStreaming] = useState("");
  const [lines, setLines] = useState([]);
  const [busy, setBusy] = useState(false);
  const [thinking, setThinking] = useState("");
  const [meta, setMeta] = useState("");
  const [provider, setProvider] = useState(null);
  const [quota, setQuota] = useState(null);
  const [transport, setTransport] = useState(null);
  const [note, setNote] = useState("");
  const [whyOpen, setWhyOpen] = useState(false);
  const [collapsed, setCollapsed] = useState(() => new Set());
  const [revealed, setRevealed] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [atBottom, setAtBottom] = useState(true);
  const [focused, setFocused] = useState(false);
  const [sampleOpen, setSampleOpen] = useState(true);
  const [recordings, setRecordings] = useState([]);
  const [turnSource, setTurnSource] = useState("live");
  const [matching, setMatching] = useState(false);

  // Full-capability "Build" mode is now public: the toggle shows for everyone
  // and the backend meters usage (turns + sandbox sessions) and can pause it
  // via the kill-switch. No client-side admin gate.
  const [buildMode, setBuildMode] = useState(false);
  // Build session: a per-visitor sandbox id (null in admin-local mode, where the
  // local workspace is the session). Spinning a microVM takes a while, so the UI
  // must wait for it — state machine: idle → creating → ready | error.
  const [buildSid, setBuildSid] = useState(null);
  // idle → creating → ready | error (technical, retryable) | blocked (quota /
  // kill-switch — a wall, not a retry). buildSessionMsg carries the human line;
  // buildQuota is the "N live runs left" readout the server reports.
  const [buildSessionState, setBuildSessionState] = useState("idle");
  const [buildSessionMsg, setBuildSessionMsg] = useState("");
  const [buildQuota, setBuildQuota] = useState(null);

  // First-run coachmark on the Explore↔Build toggle. The mode switch is the
  // easiest thing on the page to miss, so a small hint points right at it (from
  // the composer, where the eye already is) instead of a page-blocking modal.
  const [showModeHint, setShowModeHint] = useState(() => {
    try {
      return !localStorage.getItem("jarvis.modehint.v1");
    } catch {
      return false;
    }
  });
  const dismissModeHint = useCallback(() => {
    setShowModeHint(false);
    try {
      localStorage.setItem("jarvis.modehint.v1", "1");
    } catch {
      // storage off (private browsing) — it just shows again next visit
    }
  }, []);

  const abortRef = useRef(null);
  const inputRef = useRef(null);
  const threadRef = useRef(null);
  const pageRef = useRef(null);
  const stoppedRef = useRef(false);
  const skipRevealRef = useRef(false);

  const forced = useMemo(() => forcedTransport(), []);

  const conversing = turns.length > 0 || busy;
  const started = conversing;
  // In Build mode the composer talks to the admin's private server, so the
  // public demo's health must not gate it.
  const disabled = busy || matching || (!buildMode && transport === "down");

  // Chips prefer a recorded turn and fall back to a live one if the
  // recordings file is missing or hasn't landed yet — the page still works
  // with nothing in public/jarvis/.
  const chips = useMemo(() => {
    if (recordings.length) {
      return recordings.map((rec) => ({
        label: rec.label,
        prompt: rec.prompt,
        recording: rec,
      }));
    }
    return SUGGESTIONS.map((s) => ({ ...s, recording: null }));
  }, [recordings]);

  const sample = useSamplePlayback(!started);
  const typed = useTypewriter(
    PLACEHOLDER_PROMPTS,
    !started && !focused && !input && transport !== "down"
  );

  // ---- entrance: lets the staggered CSS animations run once, after mount ----
  useEffect(() => {
    const id = requestAnimationFrame(() => setRevealed(true));
    return () => cancelAnimationFrame(id);
  }, []);

  // ---- the recorded turns behind the suggestion chips ----
  // Fetched rather than bundled: 43KB of captured frames should not sit in the
  // route's chunk when most visitors never click a chip.
  useEffect(() => {
    let cancelled = false;
    loadRecordings().then((list) => {
      if (!cancelled) setRecordings(list);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // ---- ambient glow follows the pointer (the CSS declares the vars) ----
  useEffect(() => {
    const page = pageRef.current;
    if (!page) return undefined;
    if (window.matchMedia && window.matchMedia("(pointer: coarse)").matches) {
      return undefined;
    }

    let frame = 0;
    let next = null;

    const flush = () => {
      frame = 0;
      if (!next) return;
      page.style.setProperty("--mouse-x", `${next.x}px`);
      page.style.setProperty("--mouse-y", `${next.y}px`);
    };

    const onMove = (event) => {
      next = { x: event.clientX, y: event.clientY };
      if (!frame) frame = requestAnimationFrame(flush);
    };

    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (frame) cancelAnimationFrame(frame);
    };
  }, []);

  // Textarea auto-resize helper
  const adjustInputHeight = useCallback(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    const newHeight = Math.min(el.scrollHeight, 150);
    el.style.height = `${Math.max(newHeight, 24)}px`;
  }, []);

  const handleInputChange = (e) => {
    setInput(e.target.value);
    adjustInputHeight();
  };

  useEffect(() => {
    let cancelled = false;
    if (forced === "replay") {
      setTransport("replay");
      return undefined;
    }

    (async () => {
      for (let attempt = 0; attempt < 2; attempt += 1) {
        const info = await health(9000);
        if (cancelled) return;
        if (info && info.ok) {
          setTransport("live");
          setProvider(info.defaultProvider);
          return;
        }
      }
      if (!cancelled) setTransport("down");
    })();

    return () => {
      cancelled = true;
    };
  }, [forced]);

  useEffect(() => () => abortRef.current?.abort(), []);

  // ---- Build session: spin a sandbox when Build is first entered ----
  // A ref (not buildSessionState) guards the one-shot, so setting the state
  // inside doesn't re-run the effect and cancel its own in-flight request.
  const buildSessionStartedRef = useRef(false);
  const startBuildSession = useCallback(() => {
    buildSessionStartedRef.current = true;
    setBuildSid(null);
    setBuildSessionMsg("");
    setBuildSessionState("creating");
    createBuildSession().then((res) => {
      if (res && res.ok) {
        setBuildSid(res.sid || null);
        if (res.quota) setBuildQuota(res.quota);
        setBuildSessionState("ready");
      } else if (res && (res.code === "quota" || res.code === "disabled")) {
        // Out of free sessions, or the owner paused public Build — a wall, not
        // a technical failure. Show the CTA, don't offer a pointless retry.
        setBuildSessionMsg(res.error || "");
        setBuildQuota(res.usage || null);
        setBuildSessionState("blocked");
      } else {
        setBuildSessionMsg((res && res.error) || "");
        setBuildSessionState("error");
      }
    });
  }, []);

  useEffect(() => {
    // Public: anyone can enter Build. The backend spins the microVM (or refuses
    // with quota/kill-switch), so no client-side admin gate is needed.
    if (buildMode && !buildSessionStartedRef.current) {
      startBuildSession();
    }
  }, [buildMode, startBuildSession]);

  // Reap the sandbox when the page unmounts.
  useEffect(() => {
    return () => {
      if (buildSid) stopBuildSession(buildSid);
    };
  }, [buildSid]);

  // ---- a stopwatch on the turn in flight ----
  useEffect(() => {
    if (!busy) {
      setElapsed(0);
      return undefined;
    }
    const began = performance.now();
    const id = setInterval(() => setElapsed(performance.now() - began), 100);
    return () => clearInterval(id);
  }, [busy]);

  // Smart auto-scroll
  useEffect(() => {
    if (!conversing) return;
    const el = threadRef.current;
    if (!el) return;

    const distanceToBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
    if (distanceToBottom < 160 || busy) {
      el.scrollTop = el.scrollHeight;
    }
  }, [conversing, turns, streaming, lines, busy, thinking]);

  useEffect(() => {
    const el = threadRef.current;
    if (el) el.scrollTop = 0;
  }, []);

  const onThreadScroll = useCallback((event) => {
    const el = event.currentTarget;
    setAtBottom(el.scrollHeight - el.scrollTop - el.clientHeight < 120);
  }, []);

  const scrollToBottom = useCallback(() => {
    const el = threadRef.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
  }, []);

  const status = useMemo(() => {
    if (matching) return { kind: "idle", label: "○ checking docs" };
    if (busy && turnSource === "recorded") {
      return { kind: "replay", label: "▸ replaying" };
    }
    if (busy && turnSource === "docs") {
      return { kind: "replay", label: "▪ from docs" };
    }
    if (busy) return { kind: "live", label: "● running" };
    if (transport === "live") return { kind: "live", label: "● live" };
    if (transport === "replay") return { kind: "replay", label: "▸ replay" };
    if (transport === "down") return { kind: "down", label: "○ offline" };
    return { kind: "idle", label: "○ connecting" };
  }, [busy, transport, turnSource, matching]);

  const honestyLine = useMemo(() => {
    if (matching) {
      return "Checking whether this is already answered in the docs…";
    }
    if (busy && turnSource === "recorded") {
      return "Replaying a turn that really ran — no model call, no quota spent.";
    }
    if (busy && turnSource === "docs") {
      return "Answering from written docs — no model call, no quota spent.";
    }
    if (transport === "live") {
      return "The real Jarvis, running serverless — read-only tools, sandboxed to its own source.";
    }
    if (transport === "down") {
      return "Jarvis isn't reachable right now. The code is on GitHub in the meantime.";
    }
    if (transport === "replay") {
      return "Replaying a recorded session — not a live model call.";
    }
    return "Checking whether Jarvis is awake…";
  }, [transport, busy, turnSource, matching]);

  // Runs one turn, whatever is serving it. `recording` replays a captured run
  // instead of calling the model; everything downstream — the trace, the
  // streaming answer, the stop button — is identical either way, because both
  // transports emit the same events.
  const ask = useCallback(
    async (prompt, { recording = null } = {}) => {
      const text = (prompt || "").trim();
      if (!text || busy) return;

      const source = recording ? "recorded" : "live";

      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      stoppedRef.current = false;
      setTurnSource(source);

      setInput("");
      if (inputRef.current) {
        inputRef.current.style.height = "auto";
      }
      setNote("");
      setMeta("");
      setLines([]);
      setStreaming("");
      setThinking("");
      setBusy(true);

      const history = turns
        .filter((t) => t.role === "user" || t.content)
        .slice(-6)
        .map((t) => ({ role: t.role, content: t.content }));

      setCollapsed((prev) => {
        const next = new Set(prev);
        turns.forEach((turn, i) => {
          if (turn.role === "assistant") next.add(i);
        });
        return next;
      });
      setTurns((prev) => [...prev, { role: "user", content: text }]);

      const assistantAt = turns.length + 1;

      let answer = "";
      let reasoning = "";
      let metaText = "";
      const trace = [];
      const indexOf = {};
      const startedAt = {};

      const onEvent = (event) => {
        switch (event.type) {
          case "status":
            setProvider(event.model || event.provider);
            // A replay must never overwrite what we know about the live
            // backend, nor move the quota counter — it costs nothing.
            if (source === "live") {
              setTransport(event.transport);
              if (event.quota) {
                setQuota(event.quota);
                if (buildMode) setBuildQuota(event.quota);
              }
            }
            break;

          case "text":
            answer += event.delta;
            setStreaming(answer);
            break;

          case "thinking":
            reasoning += event.delta;
            setThinking(reasoning);
            break;

          case "tool_start":
            startedAt[event.id] = performance.now();
            indexOf[event.id] = trace.length;
            trace.push({
              kind: "tool",
              step: trace.filter((l) => l.kind === "tool").length + 1,
              icon: event.icon,
              verb: event.verb,
              name: event.name,
              detail: event.detail,
              state: "running",
            });
            setLines([...trace]);
            break;

          case "tool_args": {
            const at = indexOf[event.id];
            if (at == null || !trace[at]) break;
            trace[at] = { ...trace[at], call: event.call };
            setLines([...trace]);
            break;
          }

          case "tool_summary": {
            const at = indexOf[event.id];
            if (at == null || !trace[at]) break;
            trace[at] = { ...trace[at], summary: event.summary };
            setLines([...trace]);
            break;
          }

          case "tool_result": {
            const at = indexOf[event.id];
            if (at == null || !trace[at]) break;
            const began = startedAt[event.id];
            trace[at] = {
              ...trace[at],
              state: "done",
              ok: event.ok,
              ms: began != null ? performance.now() - began : null,
            };
            setLines([...trace]);
            break;
          }

          case "failover":
            trace.push({
              kind: "warn",
              text: `⚠ ${event.from} unavailable — failing over to ${event.to}`,
            });
            setLines([...trace]);
            break;

          case "done":
            metaText = `${event.toolCalls} tool${
              event.toolCalls === 1 ? "" : "s"
            } · ${(event.ms / 1000).toFixed(1)}s · ${event.inTokens} in / ${
              event.outTokens
            } out`;
            setMeta(metaText);
            break;

          case "error":
            if (
              buildMode &&
              (event.code === "quota" || event.code === "disabled")
            ) {
              // In Build, a turn-level quota/kill-switch hit becomes the same
              // wall the session start shows — lock the composer, offer the CTA.
              setBuildSessionMsg(event.message || "");
              setBuildSessionState("blocked");
            } else if (event.code === "quota") {
              setNote(
                "You've used today's free questions. The live demo is rate-limited so the free-tier keys survive the day — come back tomorrow, or read the source on GitHub."
              );
            } else if (event.code === "busy") {
              setNote(
                "Jarvis is answering someone else. Try again in a moment."
              );
            } else {
              setNote(event.message || "Something went wrong.");
            }
            trace.push({
              kind: "err",
              text: `✗ ${event.message || event.code}`,
            });
            setLines([...trace]);
            break;

          default:
            break;
        }
      };

      if (recording) {
        await playRecording(recording, { onEvent, signal: controller.signal });
      } else if (buildMode) {
        // The admin's full agent — write + execute — in the session sandbox.
        await runFullTurn({
          prompt: text,
          history,
          sid: buildSid,
          signal: controller.signal,
          onEvent,
        });
      } else {
        await runTurn({
          prompt: text,
          history,
          signal: controller.signal,
          onEvent,
        });
      }

      // A turn the visitor stopped is not a turn that failed — say so in the
      // trace rather than leaving a half-answer with no explanation.
      if (stoppedRef.current) {
        trace.push({ kind: "warn", text: "■ stopped by you" });
        metaText = metaText || "stopped";
      }

      setBusy(false);
      setStreaming("");
      setLines([]);
      setThinking("");
      setMeta("");
      setTurns((prev) => [
        ...prev,
        {
          role: "assistant",
          content: answer,
          lines: trace,
          thinking: reasoning,
          meta: metaText,
          stopped: stoppedRef.current,
          source,
          capturedAt: recording ? recording.capturedAt : null,
        },
      ]);

      if (answer.trim()) {
        setCollapsed((prev) => new Set(prev).add(assistantAt));
      }
    },
    [busy, turns, buildMode, buildSid]
  );

  // Answers a question the docs already cover, with no model call at all.
  //
  // The text is revealed progressively rather than dumped. There is a real
  // question about whether that's honest, and the answer is that the badge is
  // what carries the honesty — the turn says "from the docs" the entire time
  // and offers the live agent. What progressive reveal buys is that a doc
  // answer reads as the same *kind* of thing as a live one instead of a
  // page-load, which is what a wall of instant text felt like next to it.
  //
  // Word by word, over a fixed budget, so a long answer isn't slower to read
  // than a short one. Stop (or Esc) reveals the remainder immediately.
  const answerFromDocs = useCallback(
    (question, entry) => {
      const text = (question || "").trim();
      if (!text || busy) return;

      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      stoppedRef.current = false;
      skipRevealRef.current = false;

      setInput("");
      if (inputRef.current) inputRef.current.style.height = "auto";
      setNote("");
      setLines([]);
      setThinking("");
      setMeta("");
      setStreaming("");
      setTurnSource("docs");

      setCollapsed((prev) => {
        const next = new Set(prev);
        turns.forEach((turn, i) => {
          if (turn.role === "assistant") next.add(i);
        });
        return next;
      });

      setTurns((prev) => [...prev, { role: "user", content: text }]);

      const full = entry.answer;
      const commit = () => {
        setBusy(false);
        setStreaming("");
        setTurns((prev) => [
          ...prev,
          {
            role: "assistant",
            content: full,
            lines: [],
            thinking: "",
            meta: "",
            source: "docs",
            docSource: entry.source,
            docSection: entry.section,
            askedLive: text,
          },
        ]);
      };

      if (prefersReducedMotion()) {
        commit();
        return;
      }

      setBusy(true);

      // Split keeping the separators, so words are never cut in half — a
      // half-written `**bold` marker flickering as literal asterisks is the
      // one artifact worth avoiding.
      const parts = full.split(/(\s+)/);
      const duration = Math.min(2400, Math.max(700, full.length * 2.2));
      const began = performance.now();

      const tick = () => {
        if (controller.signal.aborted) return;
        if (skipRevealRef.current) {
          commit();
          return;
        }
        const progress = Math.min(1, (performance.now() - began) / duration);
        // Ease-out: quick off the mark, settling at the end, which is roughly
        // how a real stream behaves once the model is warmed up.
        const eased = 1 - Math.pow(1 - progress, 2);
        const upto = Math.max(1, Math.ceil(parts.length * eased));
        setStreaming(parts.slice(0, upto).join(""));
        if (progress < 1) requestAnimationFrame(tick);
        else commit();
      };

      requestAnimationFrame(tick);
    },
    [busy, turns]
  );

  // The typed-question entry point, cheapest route first:
  //
  //   keyword match  → instant, offline, exact phrasings
  //   semantic match → ~200ms, catches paraphrases the phrase list misses
  //   live agent     → costs one of three daily questions
  //
  // The semantic step only runs on a keyword miss, so a question the pack
  // already knows verbatim never waits on the network.
  const submit = useCallback(
    async (question, { forceLive = false } = {}) => {
      const text = (question || "").trim();
      if (!text || busy || matching) return;

      // Build mode never routes through the recorded/doc cache — the whole point
      // is to run a real, unclamped turn. But wait until the sandbox is ready,
      // or the turn goes out with no session and the server rejects it.
      if (forceLive || buildMode) {
        if (buildMode && buildSessionState !== "ready") return;
        ask(text);
        return;
      }

      const hit = matchKnowledge(text);
      if (hit) {
        answerFromDocs(text, hit.entry);
        return;
      }

      // Clear the composer now: the question has been accepted, and leaving
      // the text sitting there through the round trip reads as a dropped
      // keystroke.
      setInput("");
      if (inputRef.current) inputRef.current.style.height = "auto";
      setMatching(true);
      let semantic = null;
      try {
        semantic = await matchSemantic(text);
      } finally {
        setMatching(false);
      }

      if (semantic) answerFromDocs(text, semantic.entry);
      else ask(text);
    },
    [ask, answerFromDocs, busy, matching, buildMode, buildSessionState]
  );

  const stop = useCallback(() => {
    if (!busy) return;
    // Stopping a doc answer means "show me the rest now", not "throw it away"
    // — there is no cost to finish it, and a truncated answer helps nobody.
    if (turnSource === "docs") {
      skipRevealRef.current = true;
      return;
    }
    stoppedRef.current = true;
    abortRef.current?.abort();
  }, [busy, turnSource]);

  const reset = useCallback(() => {
    abortRef.current?.abort();
    setTurns([]);
    setCollapsed(new Set());
    setNote("");
    setInput("");
    setAtBottom(true);
    setTurnSource("live");
    const el = threadRef.current;
    if (el) el.scrollTop = 0;
    inputRef.current?.focus();
  }, []);

  const toggleTrace = useCallback((index) => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  }, []);

  // ---- keyboard: ⌘K / ctrl-K anywhere focuses the composer ----
  useEffect(() => {
    const onKey = (event) => {
      const key = event.key?.toLowerCase();
      if ((event.metaKey || event.ctrlKey) && key === "k") {
        event.preventDefault();
        inputRef.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const onKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      submit(input);
    } else if (event.key === "Escape") {
      if (busy) {
        stop();
      } else if (input) {
        setInput("");
        if (inputRef.current) inputRef.current.style.height = "auto";
      } else if (inputRef.current) {
        inputRef.current.blur();
      }
    }
  };

  const handleClearInput = () => {
    setInput("");
    if (inputRef.current) {
      inputRef.current.style.height = "auto";
      inputRef.current.focus();
    }
  };

  const placeholder =
    transport === "down"
      ? "Jarvis is offline right now…"
      : started
      ? "Ask a follow-up…"
      : typed
      ? typed
      : "Ask Jarvis about its own code…";

  // Build mode replaces the chat page with the IDE. Public: anyone can enter;
  // the backend meters turns + sandbox sessions and can pause via the
  // kill-switch, surfaced here as the "blocked" session state.
  if (buildMode) {
    return (
      <div
        className="jv-page jv-revealed"
        data-theme={theme?.name}
        style={{
          "--jv-body": theme?.body,
          "--jv-text": theme?.text,
          "--jv-sub": theme?.secondaryText,
          "--jv-accent": theme?.accentColor,
        }}
      >
        <Header theme={theme} setTheme={setTheme} />
        <JarvisBuild
          agent={{
            turns,
            busy,
            streaming,
            lines,
            thinking,
            meta,
            input,
            setInput,
            submit,
            stop,
            provider,
          }}
          refreshKey={turns.length}
          sid={buildSid}
          sessionState={buildSessionState}
          sessionMessage={buildSessionMsg}
          quota={buildQuota}
          onRetrySession={startBuildSession}
          onExit={() => setBuildMode(false)}
        />
      </div>
    );
  }

  return (
    <div
      ref={pageRef}
      className={`jv-page ${revealed ? "jv-revealed" : ""} ${
        busy ? "jv-page-busy" : ""
      }`}
      data-theme={theme?.name}
      style={{
        "--jv-body": theme?.body,
        "--jv-text": theme?.text,
        "--jv-sub": theme?.secondaryText,
        "--jv-accent": theme?.accentColor,
      }}
    >
      <Header theme={theme} setTheme={setTheme} />

      {/* A hairline that fills while a turn is in flight — the page-level
          equivalent of the stopwatch on the trace. */}
      <div
        className={`jv-progress ${busy || matching ? "jv-progress-on" : ""}`}
      />

      <div className="jv-shell">
        {/* ---------------- TRANSCRIPT ---------------- */}
        <div
          className="jv-thread"
          ref={threadRef}
          onScroll={onThreadScroll}
          role="log"
          aria-live="polite"
        >
          <div className="jv-thread-inner">
            <Intro expanded={whyOpen} onToggle={() => setWhyOpen((v) => !v)} />

            {!started && (
              <div className="jv-turn jv-turn-assistant jv-turn-sample">
                <Trace
                  sample
                  open={sampleOpen}
                  onToggle={() => setSampleOpen((v) => !v)}
                  lines={sample.lines}
                  thinking={sample.thinking}
                  meta={sample.meta}
                  busy={false}
                  action={
                    <button
                      type="button"
                      className="jv-replay"
                      onClick={sample.replay}
                      disabled={sample.playing}
                      title="Play the example turn again"
                    >
                      ↻ replay
                    </button>
                  }
                />
              </div>
            )}

            {turns.map((turn, i) =>
              turn.role === "user" ? (
                <div className="jv-turn jv-turn-user" key={i}>
                  <p className="jv-user-text">{turn.content}</p>
                </div>
              ) : (
                <div className="jv-turn jv-turn-assistant" key={i}>
                  {(turn.lines.length > 0 || turn.thinking) && (
                    <Trace
                      lines={turn.lines}
                      thinking={turn.thinking}
                      meta={turn.meta}
                      busy={false}
                      open={!collapsed.has(i)}
                      onToggle={() => toggleTrace(i)}
                    />
                  )}
                  {turn.content.trim() ? (
                    <div className="jv-assistant-wrapper">
                      <CopyButton text={turn.content} />
                      <MdLite text={turn.content} />
                      <SourceNote
                        turn={turn}
                        disabled={disabled}
                        onAskLive={() => ask(turn.askedLive, {})}
                      />
                    </div>
                  ) : turn.stopped ? (
                    <p className="jv-noanswer">
                      Stopped before it answered. The trace above shows how far
                      it got.
                    </p>
                  ) : turn.lines.some((l) => l.kind === "err") ? null : (
                    <p className="jv-noanswer">
                      Jarvis ran out of tool calls before it answered. The trace
                      above shows where they went — a narrower question usually
                      gets there.
                    </p>
                  )}
                </div>
              )
            )}

            {busy && (
              <div className="jv-turn jv-turn-assistant">
                {/* A doc answer has no machinery to show — rendering a trace
                    that says "Step 1 of 0" would be inventing one. */}
                {turnSource !== "docs" && (
                  <Trace
                    lines={lines}
                    thinking={thinking}
                    meta={meta}
                    busy
                    open
                    elapsed={`${(elapsed / 1000).toFixed(1)}s`}
                    onToggle={() => {}}
                  />
                )}
                {streaming && (
                  <div className="jv-assistant-wrapper">
                    <MdLite text={streaming} />
                    <span className="jv-caret" aria-hidden="true" />
                  </div>
                )}
              </div>
            )}

            {note && (
              <p className="jv-note" role="alert">
                {note}
              </p>
            )}
          </div>
        </div>

        {/* ---------------- COMPOSER (pinned) ---------------- */}
        <div className="jv-dock">
          <button
            type="button"
            className={`jv-jump ${started && !atBottom ? "jv-jump-on" : ""}`}
            onClick={scrollToBottom}
            aria-hidden={!started || atBottom}
            tabIndex={started && !atBottom ? 0 : -1}
          >
            ↓ latest
          </button>

          <div className="jv-dock-inner">
            {!started && (
              <div className="jv-chips">
                {chips.map((chip, i) => (
                  <button
                    key={chip.label}
                    type="button"
                    className={`jv-chip ${
                      chip.recording ? "jv-chip-recorded" : ""
                    }`}
                    style={{ "--i": i }}
                    disabled={busy || (!chip.recording && transport === "down")}
                    onClick={() =>
                      ask(chip.prompt, { recording: chip.recording })
                    }
                    title={
                      chip.recording
                        ? `${chip.prompt}\n\nA real turn recorded on ${chip.recording.capturedAt} — replaying it costs none of your ${QUOTA_HINT}.`
                        : chip.prompt
                    }
                  >
                    {chip.recording && (
                      <span className="jv-chip-dot" aria-hidden="true" />
                    )}
                    {chip.label}
                  </button>
                ))}
              </div>
            )}

            <div
              className={`jv-composer ${busy ? "jv-composer-busy" : ""} ${
                showModeHint && !buildMode ? "jv-composer-hinting" : ""
              }`}
            >
              <div className="jv-input-wrap">
                <span className="jv-prompt-symbol" aria-hidden="true">
                  ›
                </span>
                <textarea
                  ref={inputRef}
                  className="jv-input"
                  aria-label="Ask Jarvis about its code"
                  placeholder={placeholder}
                  value={input}
                  rows={1}
                  maxLength={500}
                  disabled={disabled}
                  onChange={handleInputChange}
                  onKeyDown={onKeyDown}
                  onFocus={() => {
                    setFocused(true);
                    // Pull the vectors down while they're still typing.
                    warmSemanticIndex();
                  }}
                  onBlur={() => setFocused(false)}
                />
                {input && !disabled && (
                  <button
                    type="button"
                    className="jv-input-clear"
                    onClick={handleClearInput}
                    title="Clear input"
                    aria-label="Clear text input"
                  >
                    ✕
                  </button>
                )}
              </div>

              <div className="jv-composer-row">
                <span className="jv-mode-wrap">
                  <button
                    type="button"
                    className={`jv-mode-toggle ${
                      buildMode ? "jv-mode-build" : ""
                    } ${showModeHint && !buildMode ? "jv-mode-nudge" : ""}`}
                    onClick={() => {
                      dismissModeHint();
                      setBuildMode((v) => !v);
                    }}
                    disabled={busy}
                    title="Explore is read-only — watch the agent reason over its own source. Build runs the full agent — write + execute — in a fresh sandbox. A few free live runs a day."
                  >
                    {buildMode ? "● Build" : "○ Explore"}
                  </button>
                  {showModeHint && !buildMode && (
                    <div className="jv-mode-hint" role="status">
                      <button
                        type="button"
                        className="jv-mode-hint-x"
                        onClick={dismissModeHint}
                        aria-label="Dismiss"
                      >
                        ✕
                      </button>
                      <span className="jv-mode-hint-title">
                        Two modes — tap to switch
                      </span>
                      <span className="jv-mode-hint-body">
                        You're in <b>Explore</b> — watch it reason over its own
                        code. Switch to <b>Build</b> to hand it a task; it
                        writes &amp; runs code in a live sandbox.
                      </span>
                      <span className="jv-mode-hint-arrow" aria-hidden="true" />
                    </div>
                  )}
                </span>{" "}
                <span className="jv-enter-hint" aria-hidden="true">
                  {busy ? "esc to stop" : focused ? "↵ send" : "⌘K"}
                </span>
                {input.length > 400 && (
                  <span className="jv-count">{input.length}/500</span>
                )}
                <span
                  className="jv-model"
                  title="The provider and model serving this turn"
                >
                  <span className="jv-model-dot" />
                  {provider || "connecting…"}
                </span>
                {busy ? (
                  <button
                    type="button"
                    className="jv-send jv-stop"
                    aria-label="Stop this turn"
                    title="Stop (Esc)"
                    onClick={stop}
                  >
                    <span className="jv-stop-square" />
                  </button>
                ) : (
                  <button
                    type="button"
                    className="jv-send"
                    aria-label="Send prompt to Jarvis"
                    disabled={disabled || !input.trim()}
                    onClick={() => submit(input)}
                  >
                    ↑
                  </button>
                )}
              </div>
            </div>

            <div className="jv-session">
              <span
                className={`jv-session-state jv-badge-${status.kind}`}
                role="status"
              >
                {status.label}
              </span>
              <span className="jv-session-note">{honestyLine}</span>
              {started && !busy && (
                <button type="button" className="jv-reset" onClick={reset}>
                  ↺ new question
                </button>
              )}
              <span className="jv-session-quota">
                <span className="jv-pips" aria-hidden="true">
                  {Array.from({ length: quota ? quota.limit : 3 }).map(
                    (_, i) => (
                      <i
                        key={i}
                        className={
                          i < (quota ? quota.remaining : 3) ? "jv-pip-on" : ""
                        }
                      />
                    )
                  )}
                </span>
                {quota
                  ? `${quota.remaining} of ${quota.limit} live left today`
                  : QUOTA_HINT}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default JarvisLive;
